# --- rd-core, by domain module ----------------------------------------------------------------
# failpoint.rs compiles to nothing without its feature; the crash matrix is its test.
# recovery-matrix.md is the table rd-core's own library test compares with the registry.
^crates/rd-core/src/failpoint\.rs$                                                        -
^crates/rd-core/recovery-matrix\.md$                                                      -
^crates/rd-core/tests/                                                                    -
^crates/rd-core/src/audit\.rs$                                                            audit data_reset api_tokens mcp
^crates/rd-core/src/(auth_flow|auth_profile|cookie_file)\.rs$                             auth_profiles media_cookie_profile browser_session capture_intake mcp
^crates/rd-core/src/session\.rs$                                                          sessions auth mfa passkeys browser_session
^crates/rd-core/src/bandwidth\.rs$                                                        bandwidth mcp
^crates/rd-core/src/capture\.rs$                                                          capture_intake captcha event_resume browser_session auth_profiles
^crates/rd-core/src/collector\.rs$                                                        capture_intake containers container_json enqueue_cancellation indexers media_cookie_profile media_manifest mirrors nzb_paused reorder replay_consent replay_restart service_switches storage_capacity torrent api_tokens mcp
^crates/rd-core/src/diagnostics\.rs$                                                      diagnostics data_reset mcp
^crates/rd-core/src/hotfolder\.rs$                                                        hotfolder_poll
^crates/rd-core/src/media/                                                                media_cookie_profile media_manifest mcp
^crates/rd-core/src/mfa\.rs$                                                              mfa passkeys auth
^crates/rd-core/src/(recording|stream|stream_schedule)\.rs$                               stream_schedules area_backup mcp
^crates/rd-core/src/storage\.rs$                                                          storage_roots storage_capacity category_move_and_reset mcp
^crates/rd-core/src/(subscription\.rs|subscription/)                                      subscriptions feeds indexers area_backup mcp
^crates/rd-core/src/toolpath\.rs$                                                         managed_tools
^crates/rd-core/src/torrent/                                                              torrent compat_qbittorrent compat_arr container_json service_switches mcp
^crates/rd-core/src/usenet\.rs$                                                           nzb_paused container_json indexers compat_sabnzbd mcp
